async function revokeSeed(seedId, revokerId, reason) {
  const now2 = new Date().toISOString();
  const seed = await getSeed(seedId);
  if (!seed) {
    throw new Error("Seed not found");
  }
  if (!seed.isActive) {
    throw new Error("Seed already revoked");
  }
  await query(`UPDATE topology_seeds
     SET is_active = 0, revoked_at = ?, revoked_by = ?, revoke_reason = ?
     WHERE id = ?`, [now2, revokerId, reason, seedId]);
  const certs = await getCertificatesForSeed(seedId);
  for (const cert of certs) {
    await query(`UPDATE topology_certificates SET is_active = 0, revoked_at = ? WHERE id = ?`, [now2, cert.id]);
  }
  const characters = await queryAll(`SELECT id, name FROM characters WHERE owner_seed_id = ?`, [seedId]);
  const kickedCharacterIds = [];
  for (const char of characters) {
    await query(`UPDATE party_memberships
       SET active = 0, left_at = ?
       WHERE character_id = ? AND active = 1`, [now2, char.id]);
    kickedCharacterIds.push(char.id);
  }
  return {
    revokedCertificates: certs.length,
    kickedCharacters: kickedCharacterIds
  };
}
