function generateInviteCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let code = "";
  for (let i = 0;i < 8; i++) {
    code += chars[Math.floor(Math.random() * chars.length)];
  }
  return code;
}
async function createInvite(campaignId, createdBy, options = {}) {
  const id = uuid();
  const code = generateInviteCode();
  const timestamp = now();
  await query(`INSERT INTO campaign_invites
     (id, campaign_id, code, default_role, created_by, created_at, expires_at, max_uses, used_count, active, used_by)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`, [
    id,
    campaignId,
    code,
    options.defaultRole || "player",
    createdBy,
    timestamp,
    options.expiresAt?.toISOString() || null,
    options.maxUses || null,
    0,
    1,
    "[]"
  ]);
  return getInviteById(id);
}
