  const id = uuid();
  const timestamp = now();
  await query(`INSERT INTO parties (id, campaign_id, name, description, is_active, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`, [id, input.campaignId, input.name, input.description || null, 1, timestamp, timestamp]);
  const created = await getParty(id);
