async function getPortals(nodeId) {
  return getConnectedEdges(nodeId, ["PORTAL", "PLANAR_GATE"]);
}
async function findPath(startId, endId, options = {}) {
  const maxDepth = options.maxDepth || 20;
  const visited = new Set;
  const queue = [
    { nodeId: startId, path: [startId], edges: [] }
  ];
  while (queue.length > 0) {
    const current = queue.shift();
    if (current.nodeId === endId) {
      return { path: current.path, edges: current.edges };
    }
    if (current.path.length > maxDepth)
      continue;
    if (visited.has(current.nodeId))
      continue;
    visited.add(current.nodeId);
    const edges = await getConnectedEdges(current.nodeId, options.types);
    for (const edge of edges) {
      const nextId = edge.sourceId === current.nodeId ? edge.targetId : edge.sourceId;
      if (!visited.has(nextId)) {
        queue.push({
          nodeId: nextId,
          path: [...current.path, nextId],
          edges: [...current.edges, edge]
        });
      }
    }
  }
  return null;
}
async function updateEdge(id, input) {
  const existing = await getEdgeById(id);
  if (!existing)
    throw new NotFoundError("WorldEdge", id);
  const updates = {
    updatedAt: now(),
    version: existing.version + 1
  };
  if (input.bidirectional !== undefined) {
    updates.bidirectional = input.bidirectional ? 1 : 0;
  }
  if (input.properties !== undefined) {
    updates.properties = toJson({
      ...existing.properties,
      ...input.properties
    });
  }
  const { sql, params } = buildUpdate("world_edges", updates, { id });
  await query(sql, params);
  return getEdgeByIdOrThrow(id);
}
async function updateEdgeProperties(id, path, value) {
  const existing = await getEdgeById(id);
  if (!existing)
    throw new NotFoundError("WorldEdge", id);
  await query(`UPDATE world_edges
     SET properties = json_set(properties, ?, ?),
         updated_at = ?,
         version = version + 1
     WHERE id = ?`, [`$.${path}`, toJson(value), now(), id]);
  return getEdgeByIdOrThrow(id);
}
async function deleteEdge(id) {
  await query("DELETE FROM world_edges WHERE id = ?", [id]);
}
async function deleteEdgesForNode(nodeId) {
  const result = await query("DELETE FROM world_edges WHERE source_id = ? OR target_id = ?", [nodeId, nodeId]);
  return result.rowsAffected;
}
async function deleteEdgesBetween(nodeId1, nodeId2) {
  const result = await query(`DELETE FROM world_edges
     WHERE (source_id = ? AND target_id = ?)
        OR (source_id = ? AND target_id = ?)`, [nodeId1, nodeId2, nodeId2, nodeId1]);
  return result.rowsAffected;
}
async function getEdgeStats() {
  const total = await queryOne("SELECT COUNT(*) as count FROM world_edges");
  const byTypeRows = await queryAll("SELECT type, COUNT(*) as count FROM world_edges GROUP BY type");
  const byType = {};
  for (const row of byTypeRows) {
    byType[row.type] = row.count;
  }
  return {
    total: total?.count || 0,
    byType
  };
}
var getEdgesFrom = getOutgoingEdges;
var getEdgesTo = getIncomingEdges;
async function getConnectedNodes(nodeId, type, direction = "both") {
  const { getNodeById: getNodeById2 } = await Promise.resolve().then(() => (init_nodes(), exports_nodes));
  let edges;
  if (direction === "from") {
    edges = await getOutgoingEdges(nodeId, type);
  } else if (direction === "to") {
    edges = await getIncomingEdges(nodeId, type);
  } else {
    edges = await getConnectedEdges(nodeId, type);
  }
  const nodeIds = new Set;
  for (const edge of edges) {
    if (edge.sourceId === nodeId) {
      nodeIds.add(edge.targetId);
    } else {
      nodeIds.add(edge.sourceId);
    }
  }
  const nodes = [];
  for (const id of nodeIds) {
    const node = await getNodeById2(id);
    if (node)
      nodes.push(node);
  }
  return nodes;
}

