async function getPartyTimelineCursor2(partyId) {
  const row = await queryOne(`SELECT party_id, version, current_time, location_id
     FROM party_timelines
     WHERE party_id = ?`, [partyId]);
  if (!row)
    return null;
  let worldTimestamp;
  try {
    worldTimestamp = JSON.parse(row.current_time);
  } catch {
    worldTimestamp = { day: 0, slot: 0, turn: 0 };
  }
  return {
    partyId: row.party_id,
    version: row.version,
    worldTimestamp,
    locationId: row.location_id ?? undefined
  };
}
async function getStateAtCursor(campaignId, cursor) {
  const deltas = await queryAll(`SELECT entity_type, entity_id, operation, delta
     FROM sync_log
     WHERE campaign_id = ?
     AND version <= ?
     ORDER BY version ASC`, [campaignId, cursor.version]);
  const state = {};
  for (const d of deltas) {
    const key = `${d.entity_type}:${d.entity_id}`;
    const delta = JSON.parse(d.delta);
    if (d.operation === "create") {
      state[key] = delta;
    } else if (d.operation === "update") {
      state[key] = { ...state[key] ?? {}, ...delta };
    } else if (d.operation === "delete") {
      delete state[key];
    }
  }
  return state;
}
