async function seedDefaultLoadouts(campaignId) {
  const { createNPCLoadout: createNPCLoadout2, getNPCLoadout: getNPCLoadout2 } = await Promise.resolve().then(() => (init_inventory(), exports_inventory));
  for (const [role, loadout] of Object.entries(DEFAULT_NPC_LOADOUTS)) {
    const existing = await getNPCLoadout2(role, undefined, undefined, campaignId);
    if (existing)
      continue;
    await createNPCLoadout2({
      ...loadout,
      occupation: loadout.occupation ?? undefined,
      role,
      campaignId
    });
  }
}

